function countSimulationSessions(schedule){
  return schedule.filter(d=>d.session.includes('Simulation')||d.session.includes('Hard')).length;
}

function isFullySimulated(conditions){
  const required=['timePressure','noHints','verbalCommunication','realisticEnvironment'];
  return required.every(key=>key in conditions);
}

